$c=new ClubChat($db,'one');$chat=$c->create('Family',['two']);$key=bin2hex(random_bytes(16));$c->send($chat,'Hello',$key);$c->send($chat,'Hello',$key);ok(count($c->messages($chat))===1,'duplicate message avoided');$other=new ClubChat($db,'two');ok($other->listing()[0]['unread']===1,'unread notification');denied(fn()=>(new ClubChat($db,'stranger'))->messages($chat),'nonparticipant denied');denied(fn()=>(new ClubChat($db,'foreign'))->messages($chat),'other club denied');$other->read($chat,$other->messages($chat)[0]['seq']);ok($other->listing()[0]['unread']===0,'read marker clears badge');$other->leave($chat);denied(fn()=>$other->messages($chat),'leaving removes access');$db->exec("UPDATE actors SET active=0 WHERE id='one'");denied(fn()=>$c->messages($chat),'disabled account denied');ok(!(\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)[0]??false),'foreign keys valid');
